INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:صرم:zabidi_taj_arus', 'صرم', '7c40d21af511fe9f941fff1be0', '(صَرَمَه يَصْرِمه صَرْماً) بالفَتْح، (ويُضُمّ) . وَقيل: الصَّرْم: المَصْدَر، والصُّرم الاسْم: (قَطَعَه بائِناً)', 'he cut it clean off', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_9b03b40bd33a144e', '497', 32, 'blk_taj_8114283ab02b34f5', 0, NULL, 'Marker: Qāmūs gloss. Reading: cutting off.', 'high', 'active');
