INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:صعر:fayyumi_misbah_munir', 'صعر', '60b68ead69c6b8bd93f6329e39', 'الصَّعَرُ مَيَلٌ فِي الْعُنُقِ وَانْقِلَابٌ فِي الْوَجْهِ إلَى أَحَدِ الشِّدْقَيْنِ', 'neck tilted, face turned to one side', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_c2bc2353a6b14ef0', '1730', NULL, 'blk_msb_0f6a2921d25b1653', 0, NULL, 'Marker: head gloss. Reading: tilted neck.', 'high', 'active');
