INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:صعق:khalil_kitab_ayn', 'صعق', 'e5e077a2196a500305de0e2efc', 'الصُّعَاقُ: الصَّوت الشَّديد للثَّور والحمارِ', 'the loud bellow of a bull or donkey', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_2352537b8ac2344f', '118', NULL, 'blk_kay_f300ceede8d5bab0', 0, NULL, 'Marker: head gloss. Reading: loud sound. Differs from the main reading (fainting from a loud sound).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:صعق:jawhari_sihah', 'صعق', 'e5e077a2196a500305de0e2efc', 'الصاعِقَةُ: نارٌ تسقُط من السماء في رعدٍ شديدٍ', 'fire falling from the sky in heavy thunder', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_856b2dbdcf73b126', '2982', 4, 'blk_sih_7c6b45c0b46fd67e', 0, NULL, 'Marker: head gloss. Reading: thunderbolt. Quoted from Abū Zayd via al-Jawharī. Differs from the main reading (fainting from a loud sound).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:صعق:raghib_mufradat', 'صعق', 'e5e077a2196a500305de0e2efc', 'الصَّاعِقَةُ والصّاقعة يتقاربان، وهما الهدّة الكبيرة', 'a great crash', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_0f0ec7bc4398c3eb', '484', 1, 'blk_mfr_caadc001bae0997c', 0, NULL, 'Marker: head gloss. Reading: great crash. Differs from the main reading (fainting from a loud sound).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:صعق:ibn_manzur_lisan_arab', 'صعق', 'e5e077a2196a500305de0e2efc', 'صَعِقَ الإِنسان صَعْقاً وصَعَقاً، فَهُوَ صَعِقٌ: غُشِيَ عَلَيْهِ وَذَهَبَ عَقْلُهُ مِنْ صَوْتٍ يَسْمَعُهُ كالهَدَّة الشَّدِيدَةِ', 'fainted from hearing a sound like a great crash', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_ca3efad23f3fb68f', '4868', 10, 'blk_lsn_84fde03026e114ba', 0, NULL, 'Marker: head gloss. Reading: fainting from noise. Primary: fainting from a loud sound — 4 of 8 books (Lisān blk_lsn_84fde03026e114ba; al-Miṣbāḥ blk_msb_9ec8c4fab8b1b803; Tāj blk_taj_883cb871b5e3b8cc; Lane blk_lane_d5c46923eb86f089). Other readings: loud crash: al-Khalīl, Ibn Fāris, al-Rāghib · thunderbolt: al-Jawharī.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:صعق:fayyumi_misbah_munir', 'صعق', 'e5e077a2196a500305de0e2efc', 'صَعِقَ صَعَقًا مِنْ بَابِ تَعِبَ مَاتَ وَصَعِقَ غُشِيَ عَلَيْهِ لِصَوْتٍ سَمِعَهُ', 'he died; he fainted at a sound', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_b40c7ceddcb68f9b', '1731', NULL, 'blk_msb_9ec8c4fab8b1b803', 0, NULL, 'Marker: head gloss. Reading: fainting or dying.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:صعق:zabidi_taj_arus', 'صعق', 'e5e077a2196a500305de0e2efc', 'والصّعْقُ أصلُه فِي الغَشْي من صَوْتٍ شَديدٍ يسمَعُه، وربّما مَاتَ مِنْهُ، ثمّ استُعمِل فِي المَوْت كثيرا', 'first fainting from a loud sound; later used for death', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_14fe85308913ebc4', '25', 26, 'blk_taj_883cb871b5e3b8cc', 0, NULL, 'Marker: «أصله». Reading: fainting from noise.', 'high', 'active');
