INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:صفر:khalil_kitab_ayn', 'صفر', '86e995aa228bbe748ed517fd10', 'الصَّفَرُ يَقَعُ في الكَبِدِ وشَراسيف الأضلاع، يقال: إنه يَلْحَسُ الانسان حتى يقتُلَه', 'a belly creature or sickness that can kill', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_a097f6f1299c3184', '2417', NULL, 'blk_kay_0da957c012473822', 0, NULL, 'Marker: head gloss. Reading: belly sickness. Differs from the main reading (yellow).', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:صفر:ibn_durayd_jamharat_lugha', 'صفر', '86e995aa228bbe748ed517fd10', 'والصَّفَر: حيّة تكون فِي الْبَطن تُعدي', 'a snake-like worm in the belly, said to spread', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_bba2a268773c7a27', '540', NULL, 'blk_jam_736d97306841500b', 0, NULL, 'Marker: head gloss. Reading: belly worm. Differs from the main reading (yellow).', 'medium', 'active');
