INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:صلي:jawhari_sihah', 'صلي', '537d7ee59a85721e51e4e2dfc8', 'وصليت اللحم وغيره أصليه صليا، مثال رميته رميا، إذا شويته', 'I roasted the meat', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_0234e25592416bee', '4763', 6, 'blk_sih_0c84096cec1cd52c', 0, NULL, 'Marker: «يقال … إذا». Reading: roasting. Filed under صلا in this book.', 'medium', 'active');
