INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:ضمر:qamus_muhit', 'ضمر', '46abaadafa09b2bd8596a30054', 'الضُّمْرُ، بالضم وبضمتين: الهُزالُ، ولَحاقُ البَطْنِ', 'thinness and a drawn-in belly', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_d876a80a9a3e59e1', NULL, NULL, 'blk_qms_79cdd6256f200251', 0, NULL, 'Marker: Qāmūs gloss. Reading: thinness.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:ضمر:zabidi_taj_arus', 'ضمر', '46abaadafa09b2bd8596a30054', 'الهُزَالُ، ولَحَاقُ البَطْن', 'thinness and a drawn-in belly', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_749729bea8067292', '401', 12, 'blk_taj_35af24b6d24e4cd7', 0, NULL, 'Marker: Qāmūs gloss. Reading: thinness.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:ضمر:lane_lexicon', 'ضمر', '46abaadafa09b2bd8596a30054', 'He (a horse, [&c.,] S, A, &c.) was, or became, lean, or light of flesh', 'the horse became lean', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_529ec344058d8d38', '1802', NULL, 'blk_lane_e8edc4f6a3dc5565', 0, NULL, 'Marker: first sense A1. Reading: thinness.', 'high', 'active');
UPDATE ar_ling_root_asl SET note_md = trim(CASE WHEN instr(coalesce(note_md,''),'Primary:') > 0 THEN substr(note_md, 1, instr(note_md,'Primary:') - 1) ELSE coalesce(note_md,'') END) || ' ' || 'Reading: thinness, hidden away.', updated_at = datetime('now') WHERE id = 'ASL:ضمر:maqayis_lugha' AND coalesce(note_md,'') NOT LIKE '%Reading:%';
UPDATE ar_ling_root_asl SET is_primary = CASE WHEN id = 'ASL:ضمر:khalil_kitab_ayn' THEN 1 ELSE 0 END, updated_at = datetime('now') WHERE root_norm = 'ضمر' AND EXISTS (SELECT 1 FROM ar_ling_root_asl WHERE id = 'ASL:ضمر:khalil_kitab_ayn' AND status <> 'rejected');
